class Solution {
  public char kthCharacter(long k, int[] operations) {
    long idx = k - 1;
    int shift = 0;
    for (int i = Math.min(operations.length, 62) - 1; i >= 0; i--) {
      if (idx >= (1L << i)) {
        idx -= 1L << i;
        shift += operations[i];
      }
    }
    return (char) ('a' + shift % 26);
  }
}
